#!/usr/bin/env python3
"""Exact stage 1 / stage 5 kernel link. Run with --out NEW_DIRECTORY.

Uses freshly extracted stage 1 objects and a symbolic execution of the stage 5
formula; no cached pickle or sampled comparison can satisfy the identity gate.
This stage is an identity check, not a replacement for stage 1/5 sign proofs.
"""
from pathlib import Path
import argparse
import json
import os
import pickle
import shutil
import subprocess
import sys
import time
import traceback

HERE=Path(__file__).resolve().parent
PKG=HERE.parents[1]


def write_json(path,data):
    tmp=path.with_suffix('.tmp')
    tmp.write_text(json.dumps(data,indent=2)+'\n')
    tmp.replace(path)


def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--out',type=Path,required=True)
    ap.add_argument('--cxx',default=None,help='C++ compiler for fresh stage 1 preflight')
    ap.add_argument('--keep-work',action='store_true',help='keep temporary stage 1 working tree')
    args=ap.parse_args()
    if not __debug__ or os.environ.get('PYTHONOPTIMIZE'):
        ap.error('Python assertions must be enabled (no -O/PYTHONOPTIMIZE)')
    out=args.out.expanduser().resolve()
    if out.exists(): ap.error('--out must not exist')
    out.mkdir(parents=True)
    started=time.monotonic()
    result=dict(stage='kernel_link',status='FAIL')
    try:
        sys.path.insert(0,str(HERE/'src'))
        import extract_stage1 as ex
        import compare
        cxx=args.cxx or ('clang++' if shutil.which('clang++') else 'g++')
        print('Extracting stage 1 objects after fresh pair/component preflight',flush=True)
        rc=ex.run_inner(PKG,out/'work',out/'stage1.pkl',out/'stage1.log',cxx)
        if rc: raise RuntimeError(f'stage 1 extraction exit {rc}; see stage1.log')
        print('Tracing stage 5 and checking all radial cells and t=-1',flush=True)
        with (out/'stage5.log').open('w') as fh:
            subprocess.run([sys.executable,'-B',str(HERE/'src/trace_stage5.py'),
                            '--stage5',str(PKG/'verify/stage5_kernelbox/src'),
                            '--out',str(out/'stage5.pkl')],stdout=fh,stderr=subprocess.STDOUT,check=True)
        # These pickles were just generated by the two subprocesses above.
        s1=pickle.loads((out/'stage1.pkl').read_bytes())
        s5=pickle.loads((out/'stage5.pkl').read_bytes())
        rows=compare.compare(s1,s5)
        controls=compare.negative_controls(s1,s5)
        write_json(out/'CELLS.json',rows)
        write_json(out/'NEGATIVE_CONTROLS.json',controls)
        result.update(status='PASS',ordered_radial_cells=25,stage1_exterior_branches=15,
                      endpoint_cells=25,stage1_pair_pieces=s1['pair_pieces'],
                      exact_polynomial_coefficients=sum(r['polynomial_coefficients'] for r in rows),
                      exact_nonpolynomial_monomials=sum(r['nonpolynomial_monomials'] for r in rows),
                      cap_denominator_checks=sum(r['cap_denominator_checks'] for r in rows),
                      negative_controls_rejected=len(controls),
                      domain='1 <= r,s <= 102597/100000; -1 <= t <= -133/250',
                      includes_B1=True,includes_B5=True,
                      identity_method='exact Q[r,s,z] coefficients and canonical function atoms',
                      singular_endpoint='exact underlying formula; certified code omits nonnegative caps',
                      sampled_diagnostics=s1['singleton_checks'],
                      stage1_preflight=s1['coordinator_status'])
        if not args.keep_work:
            shutil.rmtree(out/'work')
        # Serialization is an internal transport, not certificate input.
        (out/'stage1.pkl').unlink()
        (out/'stage5.pkl').unlink()
    except Exception as exc:
        result['error']=f'{type(exc).__name__}: {exc}'
        traceback.print_exc()
    result['seconds']=round(time.monotonic()-started,2)
    write_json(out/'RESULT.json',result)
    print(json.dumps(result,indent=2),flush=True)
    return 0 if result['status']=='PASS' else 1


if __name__=='__main__':
    raise SystemExit(main())
